<script setup lang="ts">
import { useGoTo } from 'vuetify';
import { ref, computed, watch } from 'vue';
import Product from "./Product.vue";
import type {IProducts, IProductUIStyles} from "../../../types/Products";

interface ProductLang {
  lang: string;
  title: string;
}

interface ProductCurrency {
  currency: string;
  price: number;
}

interface ApiProduct {
  id: number;
  sku: string;
  image: string;
  image2: string;
  details: any;
  langs: ProductLang[];
  currencies: ProductCurrency[];
}

interface ApiResponse {
  data: ApiProduct[];
  last_page: number;
}

const props = defineProps<{
  selectedCategory: number | null;
  productIds?: string | null;
  locale: string;
  uiStyles: IProductUIStyles;
}>();

const goTo = useGoTo();
const config = useRuntimeConfig();

const productsSection = ref<HTMLElement | null>(null);
const page = ref<number>(1);
watch(
    () => props.selectedCategory,
    (newCategory, oldCategory) => {
      page.value = 1;
    }
);
const scrollToProducts = (): void => {
  if (productsSection.value) {
    goTo(productsSection.value, {
      duration: 400,
      easing: 'easeInOutCubic',
      offset: -100,
    });
  }
};

const isChangingPage = ref<boolean>(false);

function onPageChange(): void {
  isChangingPage.value = true;
  scrollToProducts();
}

const { data: productsData, pending: productsPending } =  useAsyncData<ApiResponse>(
    () => `products-${props.selectedCategory ?? 'all'}-${props.productIds ?? 'none'}-${page.value}`,
    () => {
      if (!props.selectedCategory && !props.productIds) {
        return Promise.resolve({ data: [], last_page: 1 });
      }

      return $fetch<ApiResponse>(`${config.public.baseUrl}/api/products/category/${props.selectedCategory ?? props.productIds}`, {
        query: {
          per_page: 5,
          page: page.value,
        }
      });
    },
    {
      watch: [() => props.selectedCategory, () => props.productIds, page],
      lazy: true,
      server: true
    }
);

const showLoading = computed<boolean>(() => productsPending.value || isChangingPage.value);

watch(productsPending, (newPending: boolean): void => {
  if (!newPending) {
    isChangingPage.value = false;
  }
});

const processedProducts = computed<IProducts[]>(() => {
  if (!productsData.value?.data) return [];

  const targetCurrency = props.locale === 'fa' ? 'IRR' : 'USD';

  return productsData.value.data.map((product: ApiProduct): IProducts => {
    const localizedLang = product.langs?.find((l) => l.lang === props.locale) || product.langs?.[0];
    const localizedPrice = product.currencies?.find((c) => c.currency === targetCurrency) || product.currencies?.[0];

    return {
      id: product.id,
      sku: product.sku,
      slug: localizedLang?.title ?? product.sku,
      label: 'New',
      name: localizedLang?.title ?? '',
      price: localizedPrice?.price.toString() ?? '0',
      currency: localizedPrice?.currency ?? targetCurrency,
      primaryImg: `${config.public.baseUrl}/${product.image}`,
      secondaryImg: `${config.public.baseUrl}/${product.image2}`,
      features: product.details
    };
  });
});
</script>

<template>
  <v-container fluid ref="productsSection" style="position:relative; min-height: 400px;">
    <v-fade-transition>
      <div
          v-if="showLoading"
          class="page-loading"
          style="position: absolute; left: 0; top: 0; width: 100%; height: 100%; background: rgba(255,255,255,0.7); z-index: 2; display: flex; align-items: center; justify-content: center;"
      >
        <v-progress-circular indeterminate color="primary"></v-progress-circular>
      </div>
    </v-fade-transition>

    <v-row>
      <v-col
          cols="12"
          md="12"
          :lg="!productIds ? 4 : 3"
          :xl="!productIds ? 4 : 3"
          v-for="product in processedProducts"
          :key="product.id"
      >
        <Product
            :product-id="product.id"
            :slug="product.slug"
            :locale="locale"
            :product="product"
            :ui-styles="uiStyles"
        />
      </v-col>
    </v-row>

    <v-row v-if="productsData && productsData.last_page > 1">
      <v-col cols="12">
        <v-pagination
            style="direction: ltr !important;"
            v-model="page"
            :length="productsData.last_page"
            @update:model-value="onPageChange"
        ></v-pagination>
      </v-col>
    </v-row>
  </v-container>
</template>

<style>
.v-pagination__list {
  direction: ltr !important;
}
</style>