<script setup lang="ts">
import {computed, ref} from 'vue'
import PurchaseModal from './PurchaseModal.vue'
import {useTrans} from "../../../../composables/useTrans";
import type {IProducts, IProductUIStyles} from "../../../types/Products";

const props = defineProps<{
  productId: number
  slug: string
  product: IProducts,
  uiStyles: IProductUIStyles,
  locale:string
}>()

const shop = useShopLocal()
const isHovered = ref(false)
const showBuyModal = ref(false)

const favActive = computed(() =>
  shop.favorites.value.some(
    (f) => f.id === props.productId && f.sku === props.product.sku
  )
)

function toggleFavorite() {
  shop.toggleFavorite({
    id: props.productId,
    sku: props.product.sku,
    slug: props.slug,
    title: props.product.name,
    price: props.product.price,
    currency: props.product.currency,
    primaryImg: props.product.primaryImg,
    secondaryImg: props.product.secondaryImg,
    label: props.product.label,
  })
}

const onConfirmPurchase = (data: { quantity: number, total: string }) => {
  shop.addToCart({
    id: props.productId,
    sku: props.product.sku,
    slug: props.slug,
    title: props.product.name,
    price: props.product.price,
    currency: props.product.currency,
    image: props.product.primaryImg,
    quantity: data.quantity,
  })
}

const detailsPath = computed(() => `/${props.locale}/products/${props.slug}`)
const { t } = useTrans()
</script>

<template>
  <v-card
      class="product-card mx-auto"
      max-width="400"
      :elevation="isHovered ? 8 : 2"
      @mouseenter="isHovered = true"
      @mouseleave="isHovered = false"
  >
    <div class="image-wrapper">
      <v-img
          :src="product.secondaryImg"
          height="100%"
          class="bg-image"
          :class="{ 'zoom-effect': isHovered }"
      />

      <v-img
          :src="product.primaryImg"
          height="100%"
          class="bg-image top-image"
          :class="{ 'faded': isHovered, 'zoom-effect': isHovered }"
      />

      <div class="image-overlay-ui pa-3">
<!--        <v-chip-->
<!--            size="x-small"-->
<!--            color="white"-->
<!--            class="font-weight-bold glass-effect pt-1"-->
<!--            variant="flat"-->
<!--        >-->
<!--          {{ product.label }}-->
<!--        </v-chip>-->

        <v-spacer/>

        <v-btn
            :icon="favActive ? 'mdi-heart' : 'mdi-heart-outline'"
            :color="favActive ? 'red' : 'white'"
            size="small"
            variant="flat"
            class="glass-effect favorite-btn"
            @click.stop="toggleFavorite"
        />
      </div>
    </div>

    <v-card-text class="pt-2">
      <div class="d-flex justify-space-between align-center mb-1">
        <span class="text-subtitle-1 font-weight-bold text-truncate">{{ product.name }}</span>
      </div>
      <div class="d-flex justify-space-between align-center mb-1">
        <div class="text-caption text-grey">SKU: {{ product.sku }}</div>
        <span class="font-weight-black text-success" style="font-size: 18px">{{ parseFloat(product.price).toLocaleString() }} {{ t[product.currency] }}</span>
      </div>
      <v-row no-gutters class="info-box pa-2 rounded-lg">
        <v-col
            v-for="(feature, index) in props.product.features.filter(f => (f.lang ?? locale) === locale)"
            :key="index"
            cols="6"
            class="text-center py-2"
            :class="{ 'border-e': index % 2 === 0, 'border-b': index < props.product.features.filter(f => (f.lang ?? locale) === locale).length - 2 }"
        >
          <div class="text-overline text-grey-darken-1">{{ t[feature.key]??feature.key }}</div>

          <div class="text-caption font-weight-bold">{{ feature.value }}</div>
        </v-col>
      </v-row>
    </v-card-text>

    <v-card-actions class="pa-4 pt-0">
      <v-btn
          v-if="uiStyles.buy.title!=='disable'"
          :color="uiStyles.buy.color"
          :variant="uiStyles.buy.variant"
          class="font-weight-bold"
          :rounded="uiStyles.buy.rounded"
          style="flex:3"
          :prepend-icon="uiStyles.buy.icon"
          @click="showBuyModal = true"
      >
        {{ uiStyles.buy.title }}
      </v-btn>
      <v-btn
          :color="uiStyles.details.color"
          :variant="uiStyles.details.variant"
          class="font-weight-bold"
          :rounded="uiStyles.details.rounded"
          style="flex:3"
          :prepend-icon="uiStyles.details.icon"
          :to="detailsPath"
      >
        {{ uiStyles.details.title }}
      </v-btn>
    </v-card-actions>
    <PurchaseModal
        :add-to-card-title="t?.confirm_and_add_to_cart??''"
        v-model="showBuyModal"
        :product="product"
        v-bind="uiStyles.buy.modal"
        :title="t?.confirm_purchase??''"
        :unit-price-title="t?.unit_price??''"
        :select-quantity-title="t?.select_quantity??''"
        :total-price-title="t?.total??''"
        @confirm="onConfirmPurchase"
    />
  </v-card>
</template>

<style scoped>
.product-card {
  border-radius: 14px !important;
  transition: all 0.3s ease;
  overflow: hidden;
}

.image-wrapper {
  position: relative;
  height: 300px;
  overflow: hidden;
}

/* Base style for both images */
.bg-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  transition: transform 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94), opacity 0.6s ease;
}

/* Primary image sits on top */
.top-image {
  z-index: 1;
}

.top-image.faded {
  opacity: 0;
}

.zoom-effect {
  transform: scale(1.1);
}

/* UI Overlay layer stays on top of everything */
.image-overlay-ui {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  z-index: 2; /* Higher than images */
}

.glass-effect {
  background: rgba(255, 255, 255, 0.7) !important;
  backdrop-filter: blur(8px);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.favorite-btn {
  transition: transform 0.2s ease;
}

.favorite-btn:hover {
  transform: scale(1.1);
}

.info-box {
  background-color: #f8f9fa;
  border: 1px solid #f1f1f1;
}
</style>